import sys
from collections import deque

def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    grid = []
    idx = 1
    for _ in range(n):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n

    dist = [[float('inf')] * n for _ in range(n)]
    dist[0][0] = 0

    dq = deque([(0, 0)])

    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]

    while dq:
        r, c = dq.popleft()

        if r == n - 1 and c == n - 1:
            break

        d = dist[r][c]

        for i in range(4):
            nr, nc = r + dr[i], c + dc[i]
            if 0 <= nr < n and 0 <= nc < n:
                weight = grid[nr][nc]
                if d + weight < dist[nr][nc]:
                    dist[nr][nc] = d + weight
                    if weight == 0:
                        dq.appendleft((nr, nc))
                    else:
                        dq.append((nr, nc))

    print(dist[n - 1][n - 1])

if __name__ == '__main__':
    main()
